select p.patient_id,p.first_name,p.last_name,p.date_of_birth,e.encounter_date,e.encounter_type,e.provider_name,c.condition_code,c.condition_description,c.onset_date,m.medication_name,m.dosage,m.frequency,m.start_date,m.end_date,l.test_name,l.result_value,l.result_unit,l.reference_range,cl.claim_id,cl.claim_date,cl.total_amount,cl.status from patients p inner join encounters e on p.patient_id=e.patient_id left join conditions c on e.encounter_id=c.encounter_id left join medications m on c.condition_id=m.condition_id left join lab_results l on e.encounter_id=l.encounter_id left join claims cl on e.encounter_id=cl.encounter_id where p.active=1 and e.encounter_date>='2025-01-01' and (c.condition_code like 'E11%' or c.condition_code like 'I10%') and cl.status in ('approved','pending') group by p.patient_id,p.first_name,p.last_name,e.encounter_date having count(distinct c.condition_id)>1 order by e.encounter_date desc,p.last_name asc
